challenges.solution:
SELECT name, price * stock AS stock_value FROM products
WHERE price * stock > 500
ORDER BY stock_value DESC;

SELECT genre, title, rating FROM books
WHERE genre IN ('Science Fiction', 'Fantasy') AND rating >= 4.5
ORDER BY genre, rating DESC, title;

SELECT name, species, age FROM pets
WHERE species IN ('dog', 'cat') AND age > 5
ORDER BY age DESC;

SELECT name, breed, owner FROM pets
WHERE breed IS NULL OR owner IS NULL
ORDER BY name;

SELECT name, species, weight_kg FROM pets
WHERE species IN ('hamster', 'rabbit', 'parrot') OR weight_kg < 5
ORDER BY weight_kg;

SELECT name || ' the ' || species AS label, owner FROM pets
WHERE owner IS NOT NULL
ORDER BY owner, name;

SELECT name, category, price FROM products
WHERE price BETWEEN 5 AND 20 AND category <> 'stationery'
ORDER BY price;

SELECT name, price, ROUND(price * 0.75, 2) AS sale_price FROM products
WHERE category IN ('electronics', 'bags')
ORDER BY sale_price DESC;

SELECT UPPER(category) AS category, name, price * stock AS stock_value FROM products
WHERE price * stock > 300
ORDER BY stock_value DESC;
